using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;using OrcaFacil.Application.Abstractions;using OrcaFacil.Domain.Entities;using OrcaFacil.Domain.Enums;using OrcaFacil.Persistence;
namespace OrcaFacil.Web.Pages.AccountAdmin.Billing;[Authorize(Policy="AccountAdmin")]public sealed class IndexModel(OrcaFacilDbContext db,ICurrentAccountService current):PageModel{public decimal Mrr{get;private set;}public int Pending{get;private set;}public IReadOnlyList<Row>Items{get;private set;}=[];public async Task<IActionResult>OnGetAsync(CancellationToken ct){if(current.AccountId is not Guid account)return Forbid();Items=await(from s in db.AccountModuleSubscriptions.AsNoTracking()join m in db.SaasModules.AsNoTracking()on s.ModuleId equals m.Id where s.AccountId==account&&!s.IsDeleted&&!m.IsDeleted orderby m.DisplayOrder select new Row(m.DisplayName,s.BillingPeriod.ToString(),s.ContractedPrice-s.DiscountAmount,s.Status.ToString())).ToListAsync(ct);Mrr=await db.AccountModuleSubscriptions.Where(x=>x.AccountId==account&&!x.IsDeleted&&x.Status==SaasModuleSubscriptionStatus.Active).SumAsync(x=>(decimal?)(x.BillingPeriod==SaasBillingPeriod.Annual?x.ContractedPrice/12:x.ContractedPrice-x.DiscountAmount),ct)??0;Pending=await db.BillingInvoices.CountAsync(x=>x.AccountId==account&&!x.IsDeleted&&(x.Status==BillingInvoiceStatus.Pending||x.Status==BillingInvoiceStatus.Overdue),ct);return Page();}public sealed record Row(string Module,string Period,decimal Price,string Status);}
